WITH valid AS (SELECT id, supplier_name, city, rating, COALESCE(rating, 0) AS rating_filled, INITCAP(TRIM(supplier_name)) AS supplier_name_title FROM suppliers WHERE city IS NOT NULL) SELECT s.id, s.supplier_name, s.rating, s.rating_filled, s.supplier_name_title, top1.cost, top1.product_price FROM valid s JOIN LATERAL (SELECT c.cost, c.price AS product_price FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) top1 ON TRUE
